-- Refresh CDC projections with tenant and venue attribution. Restart the analytics worker after applying.
LOCK TABLE transactions, credit_settlements, credit_settlement_items, usage_sessions, users, plans, player_plan_balances, devices, cash_registers, cash_deposits, expenses, expense_categories, products, vendors, inventory_locations, stock_receipts, stock_receipt_lines, stock_waste_events, stock_waste_lines, location_stock, inventory_reorder_rules, purchase_orders, stock_transfer_requests, stock_movements, transaction_products, shifts, games, organization_memberships IN SHARE ROW EXCLUSIVE MODE;
DROP TRIGGER IF EXISTS analytics_capture ON transactions;
CREATE TRIGGER analytics_capture AFTER INSERT OR UPDATE OR DELETE ON transactions FOR EACH ROW EXECUTE FUNCTION analytics_capture_change('id,createdAt,updatedAt,deletedAt,playerId,planId,amount,paymentMethod,paymentStatus,transactionType,cashAmount,onlineAmount,paidAmount,transactionDate,shiftId,createdBy,organizationId,venueLocationId');
INSERT INTO analytics_outbox(source_table,row_id,row_data) SELECT 'transactions', t.id, (SELECT jsonb_object_agg(key,value) FROM jsonb_each(to_jsonb(t)) WHERE key=ANY(string_to_array('id,createdAt,updatedAt,deletedAt,playerId,planId,amount,paymentMethod,paymentStatus,transactionType,cashAmount,onlineAmount,paidAmount,transactionDate,shiftId,createdBy,organizationId,venueLocationId',','))) FROM transactions t;
